SELECT json_extract(report_detail,'$') as report_detail from analysis_report ar 
INNER JOIN sample_file sf on ar.subbarcode = sf.subbarcode
INNER JOIN disease_class dc on ar.primary_cancer_id = dc.class_id
where CONCAT(ar.report_file_path,ar.report_filename) is not null and sf.customer is not null and ar.status = "报告发送成功" 

	and ar.product_name = #{product_name}


	and sf.customer = #{customer}


	and ar.report_time > #{analysis_date_B}


	and ar.report_time < #{analysis_date_N}

SELECT ar.report_id as report_id,ar.subbarcode as subbarcode,ar.product_name as product_name,ar.analysis_date as analysis_date from analysis_report ar 
INNER JOIN sample_file sf on ar.subbarcode = sf.subbarcode
INNER JOIN disease_class dc on ar.primary_cancer_id = dc.class_id
where CONCAT(ar.report_file_path,ar.report_filename) is not null and sf.customer is not null and ar.status = "报告发送成功" 

	and ar.product_name = #{product_name}


	and sf.customer = #{customer}


	and ar.report_time > #{analysis_date_B}


	and ar.report_time < #{analysis_date_N}

		SELECT gene,mutFreq,ori_variant,variant,ExonicFunc,transcript,'体系' as type from this_genetic_marker_en7_vw2 WHERE report_id = #{report_id}
  		UNION
  		SELECT Gene as gene, Zygosity as mutFreq, ori_variant as ori_variant, variant as variant, ExonicFunc AS ExonicFunc,Transcript as transcript,'胚系' as type FROM cr_evw WHERE report_id = #{report_id}
  		order by gene

